package com.airesumebuilder.feature.job.service;
import com.airesumebuilder.common.exception.ResourceNotFoundException;import jakarta.validation.constraints.NotBlank;import jakarta.validation.constraints.Size;import java.sql.*;import java.time.Instant;import java.util.List;import org.springframework.jdbc.core.JdbcTemplate;import org.springframework.stereotype.*;import org.springframework.transaction.annotation.Transactional;
@Service public class JobService{private final JobRepository repo;public JobService(JobRepository r){repo=r;}@Transactional(readOnly=true)public List<Job>list(String e){return repo.list(e);}@Transactional(readOnly=true)public Job get(String e,long id){return repo.get(e,id);}@Transactional public Job create(String e,Request r){return repo.create(e,r);}@Transactional public void delete(String e,long id){repo.delete(e,id);}public record Request(@Size(max=255)String title,@Size(max=255)String companyName,@NotBlank String content,@Size(max=100)String seniorityLevel){}public record Job(long id,String title,String companyName,String content,String seniorityLevel,Instant createdAt){} }
@Repository class JobRepository{private final JdbcTemplate j;JobRepository(JdbcTemplate j){this.j=j;}List<JobService.Job>list(String e){return j.query("SELECT d.* FROM job_descriptions d JOIN users u ON u.id=d.user_id WHERE u.email=? AND d.deleted_at IS NULL ORDER BY d.created_at DESC",this::map,e);}JobService.Job get(String e,long id){return j.query("SELECT d.* FROM job_descriptions d JOIN users u ON u.id=d.user_id WHERE u.email=? AND d.id=? AND d.deleted_at IS NULL",this::map,e,id).stream().findFirst().orElseThrow(()->new ResourceNotFoundException("Job description not found."));}JobService.Job create(String e,JobService.Request r){j.update("INSERT INTO job_descriptions(user_id,title,company_name,content,seniority_level,is_external,created_at,updated_at) SELECT id,?,?,?,?,FALSE,NOW(6),NOW(6) FROM users WHERE email=? AND deleted_at IS NULL",r.title(),r.companyName(),r.content(),r.seniorityLevel(),e);Long id=j.queryForObject("SELECT LAST_INSERT_ID()",Long.class);return get(e,id);}void delete(String e,long id){if(j.update("UPDATE job_descriptions d JOIN users u ON u.id=d.user_id SET d.deleted_at=NOW(6) WHERE u.email=? AND d.id=? AND d.deleted_at IS NULL",e,id)==0)throw new ResourceNotFoundException("Job description not found.");}private JobService.Job map(ResultSet r,int n)throws SQLException{return new JobService.Job(r.getLong("id"),r.getString("title"),r.getString("company_name"),r.getString("content"),r.getString("seniority_level"),r.getTimestamp("created_at").toInstant());}}
